def get_sources(
    region: Region,
    source_types: set[SourceType],
    *,
    include_non_recommended: bool = False,
) -> list[str]:
    """Return matching enabled sources ordered by descending MVP priority."""
    matching_sources = (
        (site, metadata)
        for site, metadata in SOURCE_CATALOG.items()
        if metadata["enabled"]
        and (include_non_recommended or metadata["recommended_for_mvp"])
        and metadata["region"] == region
        and metadata["source_type"] in source_types
    )
    return [
        site
        for site, _ in sorted(
            matching_sources,
            key=lambda item: (-item[1]["priority"], item[0]),
        )
    ]
